-- Generated cleanly from themes/univers/manifest.json via scripts/gen-seed-univers.mjs

INSERT INTO themes (id, site_id, slug, name, author, version, description, preview_image, is_active, status, metadata, current_version_id) VALUES (
  'theme_univers', 'site_default', 'univers', 'Walnut Univers (官方全功能旗舰主题)', 'Walnut Edge CMS Team', '0.9.1', '集多设备响应式、中英双语、自定义 Markdown 容器、动态槽位配额、母版页夹心拼装、@api 数据直连（微内容/数据集/多媒体）及双向链接图谱于一体的官方门面与起步主题。', '/theme/univers/preview.png', 1, 'published',
  '{"id":"theme_univers","slug":"univers","name":"Walnut Univers (官方全功能旗舰主题)","author":"Walnut Edge CMS Team","version":"0.9.1","description":"集多设备响应式、中英双语、自定义 Markdown 容器、动态槽位配额、母版页夹心拼装、@api 数据直连（微内容/数据集/多媒体）及双向链接图谱于一体的官方门面与起步主题。","preview_image":"/theme/univers/preview.png","custom_css":"/* Univers Theme Custom CSS */\n.univers-custom-glow { box-shadow: 0 0 28px -6px color-mix(in srgb, var(--edge-primary, #342E7A) 32%, transparent); }\n.univers-locale-pill { transition: color 0.15s ease, background-color 0.15s ease; }\n.univers-carousel-track { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1.25rem; }\n@media (max-width: 768px) { .univers-carousel-track { grid-template-columns: repeat(1, minmax(0, 1fr)); } }","custom_js":"/* Univers Theme Injected Custom JS */\n(function() {\n  if (typeof window !== ''undefined'') {\n    var ctx = window.__EDGE__ || {};\n    document.documentElement.setAttribute(''data-edge-theme'', ''univers'');\n    if (ctx.page && ctx.page.locale) {\n      document.documentElement.setAttribute(''data-page-locale'', ctx.page.locale);\n    }\n  }\n})();","locales":{"zh-CN":{"edge_status":"Cloudflare 边缘节点直出就绪","reading_unit":"分钟深度阅读","outline_title":"本文目录","backlinks_title":"反向双链","switch_lang_label":"语言版本","read_more":"了解更多","view_details":"查看详情","loading_outline":"正在解析文档大纲...","prev_label":"上一篇","next_label":"下一篇","form_name":"称呼","form_name_placeholder":"您的姓名或昵称","form_email":"邮箱 *","form_message":"留言内容","form_message_placeholder":"写下您的想法、合作咨询或建议...","form_submit":"发送消息"},"en-US":{"edge_status":"Cloudflare Edge SSR Active","reading_unit":"min read","outline_title":"On This Page","backlinks_title":"Backlinks","switch_lang_label":"Languages","read_more":"Learn more","view_details":"View details","loading_outline":"Loading outline...","prev_label":"Previous","next_label":"Next","form_name":"Name","form_name_placeholder":"Your name","form_email":"Email *","form_message":"Message","form_message_placeholder":"Share your thoughts, project inquiry, or note...","form_submit":"Send Message"}},"tokens":{"primaryColor":"#342E7A","borderRadius":"1rem","fontFamily":"Inter, system-ui, sans-serif","primaryColorDark":"#8B7CF6"},"md_components":{"callout":"<div class=\"univers-md-callout\"><span class=\"text-lg leading-none select-none\">💡</span><div class=\"flex-1 text-sm text-slate-800 dark:text-slate-200 leading-relaxed\">{{content}}</div></div>","tip":"<div class=\"univers-md-tip\"><span class=\"text-lg leading-none select-none\">✨</span><div class=\"flex-1 text-sm text-slate-800 dark:text-slate-200 leading-relaxed\">{{content}}</div></div>","warning":"<div class=\"univers-md-warning\"><span class=\"text-lg leading-none select-none\">⚠️</span><div class=\"flex-1 text-sm text-slate-800 dark:text-slate-200 leading-relaxed\">{{content}}</div></div>","quote":"<blockquote class=\"univers-md-quote\"><div class=\"text-sm text-slate-800 dark:text-slate-200 leading-relaxed\">{{content}}</div></blockquote>","step":"<div class=\"univers-md-step\"><span class=\"text-base font-bold univers-accent-text select-none\">▸</span><div class=\"flex-1 text-sm text-slate-800 dark:text-slate-200 leading-relaxed\">{{content}}</div></div>"},"components":[{"slug":"univers-navbar","name":"顶栏导航 (Univers Navbar)","title":"顶栏导航 (Univers Navbar)","category":"navigation","icon":"menu","slots":["header"],"description":"全局顶部导航栏，限 header 槽位，含品牌与菜单","summary":"响应式顶部导航栏，支持 default / minimal 风格、多语言切换、明暗切换与移动端抽屉。","ui_schema":[{"key":"variant","label":"导航风格","widget":"select","type":"select","options":[{"label":"Default (带右侧行动按钮)","value":"default"},{"label":"Minimal (极简纯导航)","value":"minimal"}],"default":"default"},{"key":"title","label":"品牌名称","type":"text","default":"Walnut Starter"},{"key":"logo_url","label":"品牌 Logo 图片 (留空则隐藏)","type":"image","default":"/theme/univers/assets/logo.svg"},{"key":"cta_text","label":"右侧行动按钮文案 (留空则隐藏)","type":"text","default":"进入后台"},{"key":"cta_link","label":"右侧行动按钮链接","type":"text","default":"/admin"},{"key":"nav_links","label":"导航菜单项","type":"json","widget":"list","item_schema":[{"key":"text","label":"菜单文字","type":"text"},{"key":"url","label":"跳转路径","type":"text"},{"key":"target","label":"打开方式 (_self | _blank)","type":"text"}],"default":[{"text":"首页","url":"/"},{"text":"项目","url":"/projects"},{"text":"导航","url":"/links"},{"text":"画廊","url":"/gallery"},{"text":"归档","url":"/archive"},{"text":"关于","url":"/about"}]}],"default_props":{"variant":"default","title":"Walnut Starter","logo_url":"/theme/univers/assets/logo.svg","cta_text":"进入后台","cta_link":"/admin","nav_links":[{"text":"首页","url":"/"},{"text":"项目","url":"/projects"},{"text":"导航","url":"/links"},{"text":"画廊","url":"/gallery"},{"text":"归档","url":"/archive"},{"text":"关于","url":"/about"}]},"template_html":"<univers-navbar data-variant=\"{{#if variant}}{{variant}}{{else}}default{{/if}}\" class=\"block w-full\">\n  <div class=\"max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between gap-4\">\n    <a href=\"/\" class=\"flex items-center gap-2.5 font-extrabold text-base tracking-tight text-slate-900 dark:text-white hover:opacity-90 transition\">\n      {{#if logo_url}}<img src=\"{{logo_url}}\" alt=\"{{site.name}}\" class=\"univers-nav-logo w-7 h-7 rounded-md object-contain\" />{{/if}}\n      <span>{{#if title}}{{title}}{{else}}{{#if brand_text}}{{brand_text}}{{else}}{{site.name}}{{/if}}{{/if}}</span>\n    </a>\n    <nav class=\"univers-desktop-nav hidden md:flex items-center gap-7 text-sm font-medium text-slate-600 dark:text-slate-300\">\n      {{#each nav_links}}\n      <a href=\"{{url}}\"{{#if target}} target=\"{{target}}\"{{/if}} class=\"univers-link-accent\">{{text}}</a>\n      {{/each}}\n    </nav>\n    <div class=\"flex items-center gap-2\">\n      {{#if translations}}\n      <div class=\"hidden sm:flex items-center gap-1 p-1 rounded-lg bg-slate-100 dark:bg-slate-800/90 text-xs font-mono\">\n        {{#each translations}}\n        <a href=\"{{url}}\" class=\"univers-locale-pill px-2 py-0.5 rounded-md transition {{#if isCurrent}}univers-pill-active font-bold{{else}}univers-link-accent text-slate-600 dark:text-slate-300 hover:bg-slate-200/70 dark:hover:bg-slate-700/70{{/if}}\"{{#if isCurrent}} aria-current=\"page\"{{/if}}>{{locale}}</a>\n        {{/each}}\n      </div>\n      {{/if}}\n      <button type=\"button\" class=\"univers-dark-toggle p-2 rounded-lg text-slate-500 hover:text-slate-900 dark:text-slate-400 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-slate-800 transition cursor-pointer\" aria-label=\"Toggle Theme\">\n        <svg class=\"w-4 h-4 dark:hidden\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.75\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"/></svg>\n        <svg class=\"w-4 h-4 hidden dark:inline\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.75\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 2v2\"/><path d=\"M12 20v2\"/><path d=\"m4.93 4.93 1.41 1.41\"/><path d=\"m17.66 17.66 1.41 1.41\"/><path d=\"M2 12h2\"/><path d=\"M20 12h2\"/><path d=\"m6.34 17.66-1.41 1.41\"/><path d=\"m19.07 4.93-1.41 1.41\"/></svg>\n      </button>\n      {{#if cta_text}}\n      <a href=\"{{cta_link}}\" class=\"univers-nav-cta univers-btn-primary hidden sm:inline-flex items-center gap-1.5 px-3.5 py-1.5 rounded-lg text-xs font-bold transition\">\n        <span>{{cta_text}}</span>\n        <span>&rarr;</span>\n      </a>\n      {{/if}}\n      <button type=\"button\" class=\"univers-drawer-toggle md:hidden p-2 rounded-lg text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 cursor-pointer\" aria-label=\"Open Menu\">☰</button>\n    </div>\n  </div>\n  <div class=\"univers-drawer-backdrop fixed inset-0 z-50 bg-slate-950/60 backdrop-blur-xs hidden md:hidden\">\n    <div class=\"univers-drawer-content fixed right-0 top-0 bottom-0 w-72 univers-card-surface p-6 shadow-2xl flex flex-col justify-between border-l univers-border-base\">\n      <div class=\"space-y-6\">\n        <div class=\"flex items-center justify-between border-b univers-border-base pb-4\">\n          <span class=\"font-bold text-base\">{{site.name}}</span>\n          <button type=\"button\" class=\"univers-drawer-close p-1.5 rounded-lg text-slate-400 hover:text-slate-700 dark:hover:text-white cursor-pointer\">✕</button>\n        </div>\n        <nav class=\"flex flex-col gap-2 text-sm font-medium text-slate-700 dark:text-slate-200\">\n          {{#each nav_links}}\n          <a href=\"{{url}}\"{{#if target}} target=\"{{target}}\"{{/if}} class=\"py-2 px-2.5 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-800 transition\">{{text}}</a>\n          {{/each}}\n        </nav>\n      </div>\n      {{#if cta_text}}\n      <a href=\"{{cta_link}}\" class=\"univers-nav-cta univers-btn-primary w-full py-2.5 text-center rounded-lg text-xs font-bold transition\">{{cta_text}}</a>\n      {{/if}}\n    </div>\n  </div>\n</univers-navbar>"},{"slug":"univers-notice-bar","name":"通告栏 (Univers Notice Bar)","title":"通告栏 (Univers Notice Bar)","category":"layout","icon":"campaign","slots":["main"],"description":"全宽或侧栏公告提示条，适合置顶通知与版本提醒","summary":"零参数槽位自适应通告组件：subnav 呈细通告条，sidebar 呈提示卡，main 呈圆角内联公告。","ui_schema":[{"key":"notice_tag","label":"状态徽章 (留空则隐藏)","type":"text","default":"GUIDE"},{"key":"notice_text","label":"通告正文","type":"text","default":"开箱即用的 Walnut Edge CMS 活说明书 · 示例条目均归类于 folder: guide"},{"key":"action_label","label":"跳转文案 (留空则隐藏)","type":"text","default":"5 分钟上手指南"},{"key":"action_url","label":"跳转链接","type":"text","default":"/hello-walnut"}],"default_props":{"notice_tag":"NEW","notice_text":"欢迎来到数字花园与个人作品集 · 最新文章与精选项目持续更新中","action_label":"浏览项目","action_url":"/projects"},"template_html":"<univers-notice-bar class=\"block w-full\" data-site-name=\"{{site.name}}\" data-site-domain=\"{{site.domain}}\" data-page-title=\"{{page.title}}\" data-page-locale=\"{{page.locale}}\" data-edge-status=\"{{i18n.edge_status}}\">\n  <div class=\"univers-notice-surface univers-muted-surface\">\n    <div class=\"univers-notice-inner text-xs text-slate-600 dark:text-slate-300\">\n      {{#if notice_tag}}<span class=\"px-2 py-0.5 rounded-md font-mono font-bold univers-badge-accent shrink-0\">{{notice_tag}}</span>{{/if}}\n      <span class=\"univers-notice-text font-medium truncate\">{{notice_text}}</span>\n      {{#if action_label}}<a href=\"{{action_url}}\" class=\"font-bold text-slate-900 dark:text-white univers-link-accent shrink-0\">{{action_label}} &rarr;</a>{{/if}}\n    </div>\n  </div>\n</univers-notice-bar>"},{"slug":"univers-hero","name":"首屏主视觉 (Univers Hero)","title":"首屏主视觉 (Univers Hero)","category":"hero","icon":"web_asset","slots":["main"],"description":"页面首屏主视觉，无图居中展示，配图自动双栏排布","summary":"默认 layout: auto，无图时自动收起媒体列居中呈现，配图自动展开双栏。","ui_schema":[{"key":"layout","label":"布局模式","widget":"select","type":"select","options":[{"label":"Auto (有图分栏 / 无图居中)","value":"auto"},{"label":"Stacked (上文下图)","value":"stacked"},{"label":"Left (左对齐纯文字)","value":"left"},{"label":"Split (强制分栏)","value":"split"},{"label":"Center (强制居中)","value":"center"}],"default":"auto"},{"key":"badge_text","label":"顶部徽章文案 (留空则隐藏)","type":"text","default":""},{"key":"headline","label":"主标题","type":"text","default":"欢迎使用 Walnut Edge CMS"},{"key":"subtitle","label":"副标题描述 (留空则隐藏)","type":"textarea","default":"轻量级边缘原生内容与页面装配引擎，支持长文、微内容、数据集与模块化主题编排。"},{"key":"primary_cta_text","label":"主按钮文案 (留空则隐藏)","type":"text","default":"5 分钟上手指南"},{"key":"primary_cta_link","label":"主按钮链接","type":"text","default":"/hello-walnut"},{"key":"secondary_cta_text","label":"次按钮文案 (留空则隐藏)","type":"text","default":"进入后台"},{"key":"secondary_cta_link","label":"次按钮链接","type":"text","default":"/admin"},{"key":"cover_image","label":"视觉配图 (留空则自动收起媒体列)","type":"image","default":""}],"default_props":{"layout":"auto","badge_text":"","headline":"欢迎使用 Walnut Edge CMS","subtitle":"轻量级边缘原生内容与页面装配引擎，支持长文、微内容、数据集与模块化主题编排。","primary_cta_text":"5 分钟上手指南","primary_cta_link":"/hello-walnut","secondary_cta_text":"进入后台","secondary_cta_link":"/admin","cover_image":""},"template_html":"<univers-hero data-layout=\"{{#if layout}}{{layout}}{{else}}auto{{/if}}\" class=\"univers-hero univers-hero-section block py-6 sm:py-10\">\n  {{#if cover_image}}\n  <div class=\"univers-hero-container univers-hero-has-visual\">\n    <div class=\"univers-hero-text space-y-5 min-w-0\">\n      {{#if badge_text}}<div class=\"inline-flex items-center gap-2 px-3 py-1 rounded-full text-xs font-mono font-bold univers-badge-accent\"><span>{{badge_text}}</span></div>{{/if}}\n      <h1 class=\"text-3xl sm:text-5xl font-bold tracking-tight text-slate-900 dark:text-white leading-[1.12]\">{{headline}}</h1>\n      {{#if subtitle}}<p class=\"text-base sm:text-lg max-w-2xl text-slate-600 dark:text-slate-300 leading-relaxed\">{{subtitle}}</p>{{/if}}\n      <div class=\"univers-hero-cta flex flex-wrap items-center gap-3 pt-2 empty:hidden\">{{#if primary_cta_text}}<a href=\"{{primary_cta_link}}\" class=\"px-5 py-2.5 rounded-lg text-sm font-bold univers-btn-primary\">{{primary_cta_text}} &rarr;</a>{{/if}}{{#if secondary_cta_text}}<a href=\"{{secondary_cta_link}}\" class=\"px-5 py-2.5 rounded-lg text-sm font-semibold bg-slate-100 dark:bg-slate-800/90 text-slate-700 dark:text-slate-200 hover:bg-slate-200/80 dark:hover:bg-slate-700/80 border border-slate-200/70 dark:border-slate-700/70 transition\">{{secondary_cta_text}}</a>{{/if}}</div>\n    </div>\n    <div class=\"univers-hero-visual w-full min-w-0\">\n      <img src=\"{{cover_image}}\" alt=\"{{headline}}\" class=\"w-full h-auto max-h-80 object-contain rounded-xl border univers-border-base bg-slate-50/70 dark:bg-slate-900/70 p-4\" />\n    </div>\n  </div>\n  {{else}}\n  <div class=\"univers-hero-container univers-hero-no-visual\">\n    <div class=\"univers-hero-text space-y-5 min-w-0\">\n      {{#if badge_text}}<div class=\"inline-flex items-center gap-2 px-3 py-1 rounded-full text-xs font-mono font-bold univers-badge-accent\"><span>{{badge_text}}</span></div>{{/if}}\n      <h1 class=\"text-3xl sm:text-5xl font-bold tracking-tight text-slate-900 dark:text-white leading-[1.12]\">{{headline}}</h1>\n      {{#if subtitle}}<p class=\"text-base sm:text-lg max-w-2xl text-slate-600 dark:text-slate-300 leading-relaxed\">{{subtitle}}</p>{{/if}}\n      <div class=\"univers-hero-cta flex flex-wrap items-center gap-3 pt-2 empty:hidden\">{{#if primary_cta_text}}<a href=\"{{primary_cta_link}}\" class=\"px-5 py-2.5 rounded-lg text-sm font-bold univers-btn-primary\">{{primary_cta_text}} &rarr;</a>{{/if}}{{#if secondary_cta_text}}<a href=\"{{secondary_cta_link}}\" class=\"px-5 py-2.5 rounded-lg text-sm font-semibold bg-slate-100 dark:bg-slate-800/90 text-slate-700 dark:text-slate-200 hover:bg-slate-200/80 dark:hover:bg-slate-700/80 border border-slate-200/70 dark:border-slate-700/70 transition\">{{secondary_cta_text}}</a>{{/if}}</div>\n    </div>\n  </div>\n  {{/if}}\n</univers-hero>"},{"slug":"univers-grid","name":"特性与卖点矩阵 (Univers Grid)","title":"特性与卖点矩阵 (Univers Grid)","category":"layout","icon":"grid_view","slots":["main"],"description":"多列特性与卖点网格，适合 2 至 4 列均分卡片展示","summary":"支持 2/3/4 列与 card / clean 风格切换，可选顶图、图标与行动链接。","ui_schema":[{"key":"section_title","label":"区块标题 (留空则隐藏)","type":"text","default":"核心架构特性"},{"key":"section_subtitle","label":"副标题描述 (留空则隐藏)","type":"text","default":"专为边缘网络打造的轻量内容与页面装配底座"},{"key":"columns","label":"桌面列数","widget":"select","type":"select","options":[{"label":"2 Columns","value":"2"},{"label":"3 Columns","value":"3"},{"label":"4 Columns","value":"4"}],"default":"3"},{"key":"variant","label":"展示风格","widget":"select","type":"select","options":[{"label":"Card (卡片)","value":"card"},{"label":"Clean (极简无框)","value":"clean"}],"default":"card"},{"key":"items","label":"特性条目","type":"json","widget":"list","item_schema":[{"key":"icon","label":"图标","type":"text"},{"key":"image","label":"顶部配图 (可选)","type":"image"},{"key":"title","label":"标题","type":"text"},{"key":"description","label":"描述","type":"textarea"},{"key":"badge","label":"标签 (可选)","type":"text"},{"key":"link","label":"详情链接 (可选)","type":"text"}],"default":[{"icon":"⚡","title":"边缘极速直出","description":"基于 Workers 与多级缓存，公开页面首字节响应控制在毫秒级。","badge":"Edge SSR"},{"icon":"🧩","title":"槽位与契约解耦","description":"主题只定义骨架与视觉契约，业务数据在页面层自由绑定装配。","badge":"Slot System"},{"icon":"🗂️","title":"多形态内容模型","description":"原生融合长文、无标题微内容与 JSON1 结构化数据集。","badge":"Hybrid CMS"}]}],"default_props":{"section_title":"核心架构特性","section_subtitle":"专为边缘网络打造的轻量内容与页面装配底座","columns":"3","variant":"card","items":[{"icon":"⚡","title":"边缘极速直出","description":"基于 Workers 与多级缓存，公开页面首字节响应控制在毫秒级。","badge":"Edge SSR"},{"icon":"🧩","title":"槽位与契约解耦","description":"主题只定义骨架与视觉契约，业务数据在页面层自由绑定装配。","badge":"Slot System"},{"icon":"🗂️","title":"多形态内容模型","description":"原生融合长文、无标题微内容与 JSON1 结构化数据集。","badge":"Hybrid CMS"}]},"data_slots":[{"key":"title","label":"标题","required":true},{"key":"description","label":"摘要描述"},{"key":"badge","label":"标签徽章"},{"key":"link","label":"详情链接"},{"key":"image","label":"顶部配图"}],"template_html":"<univers-grid data-columns=\"{{#if columns}}{{columns}}{{else}}3{{/if}}\" data-variant=\"{{#if variant}}{{variant}}{{else}}card{{/if}}\" class=\"block space-y-8\">\n  <div class=\"text-center max-w-2xl mx-auto space-y-2.5 empty:hidden\">\n    {{#if section_title}}<h2 class=\"text-2xl sm:text-3xl font-bold tracking-tight text-slate-900 dark:text-white\">{{section_title}}</h2>{{else}}{{#if grid_title}}<h2 class=\"text-2xl sm:text-3xl font-bold tracking-tight text-slate-900 dark:text-white\">{{grid_title}}</h2>{{/if}}{{/if}}\n    {{#if section_subtitle}}<p class=\"text-sm text-slate-500 dark:text-slate-400\">{{section_subtitle}}</p>{{else}}{{#if grid_subtitle}}<p class=\"text-sm text-slate-500 dark:text-slate-400\">{{grid_subtitle}}</p>{{/if}}{{/if}}\n  </div>\n  <div class=\"univers-grid-items\">\n    {{#each items}}\n    