s font-bold univers-accent-text hover:underline\">{{#if cta_text}}{{cta_text}}{{else}}{{#if i18n.read_more}}{{i18n.read_more}}{{else}}Learn more{{/if}}{{/if}} &rarr;</a>\n      </div>\n      {{/if}}{{/if}}\n    </div>\n    {{/each}}\n  </div>\n</univers-grid>"},{"slug":"univers-cards","name":"对比与轮播卡片 (Univers Cards)","title":"对比与轮播卡片 (Univers Cards)","category":"layout","icon":"view_carousel","slots":["main"],"description":"中大型推荐对比卡片，适合方案对比、精选推荐或案例","summary":"通用多卡片对比与轮播组件，适用于方案对比、推荐精选或案例展示。","ui_schema":[{"key":"heading","label":"区块标题 (留空则隐藏)","type":"text","default":"精选方案与场景"},{"key":"subtitle","label":"副标题描述 (留空则隐藏)","type":"text","default":"按需组合不同能力卡片，超过 3 张自动启用分页轮播"},{"key":"items","label":"卡片列表","type":"json","widget":"list","item_schema":[{"key":"badge","label":"角标 (可选)","type":"text"},{"key":"price_tag","label":"副标签 / 价格 (可选)","type":"text"},{"key":"title","label":"卡片标题","type":"text"},{"key":"description","label":"描述","type":"textarea"},{"key":"meta","label":"底部说明 (可选)","type":"text"},{"key":"link","label":"跳转链接 (可选)","type":"text"},{"key":"featured","label":"高亮推荐","type":"boolean"}],"default":[{"badge":"Starter","title":"个人博客与知识库","description":"结合长文阅读器、TOC 大纲、Wiki 双链与无标题微内容流，专注内容沉淀。","meta":"Article + Micro + Timeline","link":"/archive","featured":false},{"badge":"Featured","title":"轻量产品与服务官网","description":"组合 Hero、特性矩阵、图文穿插、FAQ 与通用联系表单，快速构建转化落地页。","meta":"Hero + Grid + FAQ + Form","link":"/hello-walnut","featured":true},{"badge":"Directory","title":"结构化作品与资源展柜","description":"通过自定义 Schema 与 @api:dataset:collection=<slug>&limit=6 协议维护作品集、工具目录或书影音清单。","meta":"Dataset Schema + Filter","link":"/projects","featured":false}]}],"default_props":{"heading":"精选方案与场景","subtitle":"按需组合不同能力卡片，超过 3 张自动启用分页轮播","items":[{"badge":"Starter","title":"个人博客与知识库","description":"结合长文阅读器、TOC 大纲、Wiki 双链与无标题微内容流，专注内容沉淀。","meta":"Article + Micro + Timeline","link":"/archive","featured":false},{"badge":"Featured","title":"轻量产品与服务官网","description":"组合 Hero、特性矩阵、图文穿插、FAQ 与通用联系表单，快速构建转化落地页。","meta":"Hero + Grid + FAQ + Form","link":"/hello-walnut","featured":true},{"badge":"Directory","title":"结构化作品与资源展柜","description":"通过自定义 Schema 与 @api:dataset:collection=<slug>&limit=6 协议维护作品集、工具目录或书影音清单。","meta":"Dataset Schema + Filter","link":"/projects","featured":false}]},"data_slots":[{"key":"title","label":"卡片标题","required":true},{"key":"description","label":"卡片描述"},{"key":"badge","label":"角标徽章"},{"key":"meta","label":"底部说明"},{"key":"link","label":"跳转链接"}],"template_html":"<univers-cards-slider class=\"univers-cards block space-y-6\">\n  <div class=\"flex flex-col sm:flex-row sm:items-end justify-between gap-4 empty:hidden\">\n    <div class=\"space-y-1.5 empty:hidden\">\n      {{#if section_title}}<h2 class=\"text-2xl sm:text-3xl font-bold tracking-tight text-slate-900 dark:text-white\">{{section_title}}</h2>{{else}}{{#if heading}}<h2 class=\"text-2xl sm:text-3xl font-bold tracking-tight text-slate-900 dark:text-white\">{{heading}}</h2>{{/if}}{{/if}}\n      {{#if subtitle}}<p class=\"text-sm text-slate-500 dark:text-slate-400\">{{subtitle}}</p>{{else}}{{#if section_subtitle}}<p class=\"text-sm text-slate-500 dark:text-slate-400\">{{section_subtitle}}</p>{{/if}}{{/if}}\n    </div>\n    <div class=\"univers-carousel-controls flex items-center gap-2 shrink-0\">\n      <button type=\"button\" class=\"univers-carousel-prev px-3 py-1.5 rounded-lg text-xs font-bold bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-200 transition cursor-pointer\" aria-label=\"Previous Slide\">&larr;</button>\n      <button type=\"button\" class=\"univers-carousel-next px-3 py-1.5 rounded-lg text-xs font-bold bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-200 transition cursor-pointer\" aria-label=\"Next Slide\">&rarr;</button>\n    </div>\n  </div>\n  <div class=\"overflow-hidden pt-4 pb-2\">\n    <div class=\"univers-carousel-track items-stretch\">\n      {{#each items}}\n      <div class=\"univers-carousel-slide p-6 rounded-xl transition-all flex flex-col justify-between space-y-5 relative {{#if featured}}univers-card-featured{{else}}univers-card-surface border univers-border-base univers-border-accent-hover{{/if}}\">\n        {{#if featured}}\n        <div class=\"absolute -top-3 left-5 px-3 py-0.5 rounded-full text-[10px] font-mono font-bold uppercase tracking-wider univers-pill-active\">{{#if badge}}{{badge}}{{else}}Featured{{/if}}</div>\n        {{/if}}\n        <div class=\"space-y-3\">\n          <div class=\"flex items-center justify-between gap-2 empty:hidden\">\n            {{#if tier_code}}<span class=\"px-2 py-0.5 rounded-md text-[11px] font-mono font-bold univers-badge-accent\">{{tier_code}}</span>{{else}}{{#if badge}}<span class=\"px-2 py-0.5 rounded-md text-[11px] font-mono font-bold univers-badge-accent\">{{badge}}</span>{{/if}}{{/if}}\n            {{#if price_tag}}<span class=\"text-sm font-mono font-bold univers-accent-text\">{{price_tag}}</span>{{/if}}\n          </div>\n          {{#if title}}<h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">{{title}}</h3>{{/if}}\n          {{#if description}}<p class=\"text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">{{description}}</p>{{else}}{{#if summary}}<p class=\"text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">{{summary}}</p>{{/if}}{{/if}}\n        </div>\n        <div class=\"pt-3.5 border-t border-slate-100 dark:border-slate-800/80 flex items-center justify-between gap-2 text-xs font-mono text-slate-500 dark:text-slate-400 empty:hidden\">\n          {{#if meta}}<span>{{meta}}</span>{{else}}{{#if meta_note}}<span>{{meta_note}}</span>{{else}}{{#if quota_info}}<span>{{quota_info}}</span>{{/if}}{{/if}}{{/if}}\n          {{#if link}}<a href=\"{{link}}\" class=\"font-bold univers-accent-text hover:underline shrink-0\">&rarr;</a>{{else}}{{#if cta_url}}<a href=\"{{cta_url}}\" class=\"font-bold univers-accent-text hover:underline shrink-0\">&rarr;</a>{{/if}}{{/if}}\n        </div>\n      </div>\n      {{/each}}\n    </div>\n  </div>\n</univers-cards-slider>"},{"slug":"univers-content-feed","name":"微内容与动态流 (Univers Content Feed)","title":"微内容与动态流 (Univers Content Feed)","category":"content","icon":"dynamic_feed","slots":["main","sidebar"],"description":"微内容与动态流列表，适合 main 或 sidebar 轻量化展示","summary":"支持 main / sidebar 双槽位自适应与 clean / card 风格，原生适配无标题微内容与 progress 徽章。","ui_schema":[{"key":"feed_title","label":"区块标题 (留空则隐藏)","type":"text","default":"微内容动态"},{"key":"feed_subtitle","label":"副标题描述 (留空则隐藏)","type":"text","default":""},{"key":"variant","label":"展示风格","widget":"select","type":"select","options":[{"label":"Clean (极简无边框文字流)","value":"clean"},{"label":"Card (微边框卡片)","value":"card"}],"default":"clean"},{"key":"items","label":"数据源协议 (@api:micro:limit=12)","type":"json","widget":"list","item_schema":[{"key":"title","label":"标题 (可选)","type":"text"},{"key":"summary","label":"微内容正文","type":"textarea"},{"key":"folder","label":"分组标签","type":"text"},{"key":"progress","label":"进度徽章","type":"text"},{"key":"date","label":"发布日期","type":"text"},{"key":"url","label":"详情链接 (可选)","type":"text"}],"default":"@api:micro:limit=12"}],"default_props":{"feed_title":"微内容动态","feed_subtitle":"","variant":"clean","items":[{"title":"","summary":"微内容支持完全无标题输入，适合记录轻量想法与更新动态。","progress":"指南","folder":"guide","date":"2026-11-18"}]},"template_html":"<univers-stream-block class=\"univers-content-feed block space-y-5\" data-variant=\"{{#if variant}}{{variant}}{{else}}clean{{/if}}\">\n  <div class=\"flex flex-col sm:flex-row sm:items-end justify-between gap-3 border-b univers-border-base pb-3.5 empty:hidden\">\n    <div class=\"space-y-1 empty:hidden\">\n      {{#if feed_title}}<h2 class=\"text-xl sm:text-2xl font-bold tracking-tight text-slate-900 dark:text-white\">{{feed_title}}</h2>{{/if}}\n      {{#if feed_subtitle}}<p class=\"text-sm text-slate-500 dark:text-slate-400\">{{feed_subtitle}}</p>{{/if}}\n    </div>\n    <div class=\"univers-feed-filter-bar inline-flex flex-wrap items-center gap-1 p-1 rounded-lg bg-slate-100 dark:bg-slate-800 text-xs font-bold empty:hidden\"></div>\n  </div>\n  <div class=\"univers-stream-container grid grid-cols-1 md:grid-cols-3 gap-5\">\n    {{#each items}}\n    <article class=\"univers-feed-card p-5 rounded-xl univers-card-surface border univers-border-base univers-border-accent-hover flex flex-col justify-between space-y-3\" data-category=\"{{#if category}}{{category}}{{else}}{{#if folder}}{{folder}}{{else}}{{progress}}{{/if}}{{/if}}\" data-progress=\"{{progress}}\" data-folder=\"{{folder}}\" data-type=\"{{type}}\">\n      <div class=\"space-y-2.5\">\n        <div class=\"flex items-center justify-between gap-2 flex-wrap empty:hidden\">\n          <div class=\"flex items-center gap-1.5 flex-wrap empty:hidden\">\n            {{#if folder}}<span class=\"univers-folder-chip px-2 py-0.5 rounded-md text-[11px] font-mono bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300\">{{folder}}</span>{{/if}}\n            {{#if progress}}<span class=\"univers-progress-badge px-2 py-0.5 rounded-md text-[11px] font-mono font-bold univers-badge-accent\">{{progress}}</span>{{/if}}\n          </div>\n          {{#if date}}<time class=\"text-[11px] font-mono text-slate-400\">{{date}}</time>{{else}}{{#if published_date}}<time class=\"text-[11px] font-mono text-slate-400\">{{published_date}}</time>{{/if}}{{/if}}\n        </div>\n        {{#if title}}<h3 class=\"text-base font-bold text-slate-900 dark:text-white leading-snug\">{{#if url}}<a href=\"{{url}}\" class=\"univers-link-accent\">{{title}}</a>{{else}}{{title}}{{/if}}</h3>{{/if}}\n        {{#if summary}}<p class=\"text-sm text-slate-700 dark:text-slate-300 leading-relaxed\">{{summary}}</p>{{else}}{{#if content_raw}}<p class=\"text-sm text-slate-700 dark:text-slate-300 leading-relaxed\">{{content_raw}}</p>{{/if}}{{/if}}\n      </div>\n      {{#if url}}<div class=\"pt-1 flex justify-end\"><a href=\"{{url}}\" class=\"text-xs font-bold univers-accent-text hover:underline\">&rarr;</a></div>{{/if}}\n    </article>\n    {{/each}}\n  </div>\n</univers-stream-block>"},{"slug":"univers-dataset-viewer","name":"结构化数据展厅 (Univers Dataset Viewer)","title":"结构化数据展厅 (Univers Dataset Viewer)","category":"data","icon":"dataset","slots":["main"],"description":"数据集绑定展厅，适合项目与书签的多布局结构化列表","summary":"绑定 @api:dataset: 展示结构化条目，支持 grid / list / compact 三种展柜布局。","ui_schema":[{"key":"title","label":"展厅标题 (留空则隐藏)","type":"text","default":"开源项目与工具清单"},{"key":"subtitle","label":"副标题描述 (留空则隐藏)","type":"text","default":"通过 @api:dataset:collection=projects&limit=6 从结构化数据集实时拉取"},{"key":"layout","label":"展柜布局","widget":"select","type":"select","options":[{"label":"Grid (展柜网格)","value":"grid"},{"label":"List (详情清单)","value":"list"},{"label":"Compact (高密度导航)","value":"compact"}],"default":"grid"},{"key":"cta_label","label":"卡片操作文案","type":"text","default":"查看详情"},{"key":"items","label":"数据源 (@api:dataset:collection=<slug>&limit=6)","type":"json","widget":"list","item_schema":[{"key":"title","label":"标题","type":"text"},{"key":"description","label":"摘要描述","type":"textarea"},{"key":"badge","label":"分类 / 徽章","type":"text"},{"key":"meta","label":"角标 / 状态备注","type":"text"},{"key":"tags","label":"技术栈 / 标签行","type":"text"},{"key":"link","label":"跳转链接","type":"url"},{"key":"image","label":"封面配图","type":"image"}],"default":"@api:dataset:collection=projects&limit=6"}],"default_props":{"title":"精选项目与作品集","subtitle":"开源实验、设计工具与持续维护的数字产品","layout":"grid","cta_label":"查看详情","items":[{"title":"Edge Static Starter","description":"轻量级边缘页面与组件模板套件，兼顾首屏加载速度与清晰视觉层次。","badge":"Starter","tags":"TypeScript · Tailwind","link":"/hello-walnut","meta":"MIT"}]},"data_slots":[{"key":"title","label":"标题","required":true},{"key":"description","label":"摘要描述"},{"key":"badge","label":"分类 / 徽章"},{"key":"meta","label":"角标 / 状态备注"},{"key":"tags","label":"技术栈 / 标签行"},{"key":"link","label":"跳转链接"},{"key":"image","label":"封面配图"}],"template_html":"<univers-dataset-viewer data-layout=\"{{#if layout}}{{layout}}{{else}}grid{{/if}}\" class=\"block space-y-6\">\n  <div class=\"space-y-1.5 border-b univers-border-base pb-3.5 empty:hidden\">\n    {{#if title}}<h2 class=\"text-xl sm:text-2xl font-bold tracking-tight text-slate-900 dark:text-white\">{{title}}</h2>{{/if}}\n    {{#if subtitle}}<p class=\"text-sm text-slate-500 dark:text-slate-400\">{{subtitle}}</p>{{/if}}\n  </div>\n  <div class=\"univers-dataset-grid\">\n    {{#each items}}\n    <div class=\"univers-dataset-card group p-5 rounded-xl univers-card-surface border univers-border-base univers-border-accent-hover flex flex-col justify-between gap-4 text-slate-900 dark:text-slate-100\">\n      <div class=\"space-y-2.5 min-w-0\">\n        {{#if image}}<div class=\"h-32 rounded-lg overflow-hidden bg-slate-50 dark:bg-slate-950 border border-slate-200/60 dark:border-slate-800 flex items-center justify-center p-2\"><img src=\"{{image}}\" alt=\"{{title}}\" class=\"max-h-full max-w-full object-contain\" /></div>{{else}}{{#if cover_image}}<div class=\"h-32 rounded-lg overflow-hidden bg-slate-50 dark:bg-slate-950 border border-slate-200/60 dark:border-slate-800 flex items-center justify-center p-2\"><img src=\"{{cover_image}}\" alt=\"{{title}}\" class=\"max-h-full max-w-full object-contain\" /></div>{{/if}}{{/if}}\n        <div class=\"flex items-center justify-between gap-2 empty:hidden\">\n          <div class=\"flex items-center gap-1.5 min-w-0\">\n            {{#if icon}}<span class=\"text-base leading-none\">{{icon}}</span>{{/if}}\n            {{#if badge}}<span class=\"px-2.5 py-0.5 rounded-full text-[11px] font-mono font-bold univers-badge-accent truncate\">{{badge}}</span>{{else}}{{#if category}}<span class=\"px-2.5 py-0.5 rounded-full text-[11px] font-mono font-bold univers-badge-accent truncate\">{{category}}</span>{{/if}}{{/if}}\n          </div>\n          {{#if meta}}<span class=\"text-[11px] font-mono text-slate-500 dark:text-slate-400 shrink-0\">{{meta}}</span>{{else}}{{#if metrics}}<span class=\"text-[11px] font-mono text-slate-500 dark:text-slate-400 shrink-0\">{{metrics}}</span>{{/if}}{{/if}}\n        </div>\n        {{#if title}}<h3 class=\"text-base font-bold text-slate-900 dark:text-white univers-group-accent transition-colors leading-snug\">{{title}}</h3>{{/if}}\n        {{#if description}}<p class=\"univers-dataset-summary text-sm text-slate-600 dark:text-slate-400 leading-relaxed line-clamp-3\">{{description}}</p>{{else}}{{#if summary}}<p class=\"univers-dataset-summary text-sm text-slate-600 dark:text-slate-400 leading-relaxed line-clamp-3\">{{summary}}</p>{{/if}}{{/if}}\n      </div>\n      <div class=\"univers-dataset-footer pt-3.5 border-t border-slate-100 dark:border-slate-800/80 flex items-center justify-between gap-3 empty:hidden\">\n        {{#if tags}}<div class=\"text-[11px] font-mono text-slate-500 dark:text-slate-400 truncate\">{{tags}}</div>{{else}}{{#if tech_stack}}<div class=\"text-[11px] font-mono text-slate-500 dark:text-slate-400 truncate\">{{tech_stack}}</div>{{/if}}{{/if}}\n        {{#if link}}\n        <a href=\"{{link}}\" class=\"inline-flex items-center gap-1 text-xs font-bold univers-accent-text hover:underline shrink-0\">\n          <span>{{#if cta_label}}{{cta_label}}{{else}}{{#if i18n.view_details}}{{i18n.view_details}}{{else}}View details{{/if}}{{/if}}</span>\n          <span>&rarr;</span>\n        </a>\n        {{else}}{{#if site_url}}\n        <a href=\"{{site_url}}\" class=\"inline-flex items-center gap-1 text-xs font-bold univers-accent-text hover:underline shrink-0\">\n          <span>{{#if cta_label}}{{cta_label}}{{else}}{{#if i18n.view_details}}{{i18n.view_details}}{{else}}View details{{/if}}{{/if}}</span>\n          <span>&rarr;</span>\n        </a>\n        {{else}}{{#if url}}\n        <a href=\"{{url}}\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"inline-flex items-center gap-1 text-xs font-bold univers-accent-text hover:underline shrink-0\">\n          <span>{{#if cta_label}}{{cta_label}}{{else}}{{#if i18n.view_details}}{{i18n.view_details}}{{else}}View details{{/if}}{{/if}}</span>\n          <span>&rarr;</span>\n        </a>\n        {{/if}}{{/if}}{{/if}}\n      </div>\n    </div>\n    {{/each}}\n  </div>\n</univers-dataset-viewer>"},{"slug":"univers-media-gallery","name":"视觉媒体画廊 (Univers Media Gallery)","title":"视觉媒体画廊 (Univers Media Gallery)","category":"media","icon":"photo_library","slots":["main","sidebar"],"description":"视觉媒体与图片画廊，支持网格展示，侧栏自动收为单列","summary":"容器宽度自适应画廊，支持 grid / strip / showcase 布局，在侧栏自动收敛为单列。","ui_schema":[{"key":"gallery_title","label":"画廊标题 (留空则隐藏)","type":"text","default":"媒体资源示例"},{"key":"gallery_subtitle","label":"副标题描述 (留空则隐藏)","type":"text","default":"通过 @api:media: 动态展示站点公开媒体资产"},{"key":"layout","label":"画廊布局","widget":"select","type":"select","options":[{"label":"Grid (自适应网格)","value":"grid"},{"label":"Strip (横向滚动胶片)","value":"strip"},{"label":"Showcase (首图跨列展陈)","value":"showcase"}],"default":"grid"},{"key":"items","label":"数据源 (@api:media:limit=6)","type":"json","widget":"list","item_schema":[{"key":"title","label":"媒体名称","type":"text"},{"key":"url","label":"图片地址","type":"image"},{"key":"mime_type","label":"格式类型","type":"text"},{"key":"folder","label":"目录分类","type":"text"}],"default":"@api:media:limit=3"}],"default_props":{"gallery_title":"媒体资源示例","gallery_subtitle":"通过 @api:media: 动态展示站点公开媒体资产","layout":"grid","items":[{"title":"logo.svg","url":"/theme/univers/assets/logo.svg","mime_type":"image/svg+xml","folder":"assets"},{"title":"pipeline.svg","url":"/theme/univers/assets/pipeline.svg","mime_type":"image/svg+xml","folder":"assets"},{"title":"slots.svg","url":"/theme/univers/assets/slots.svg","mime_type":"image/svg+xml","folder":"assets"}]},"template_html":"<univers-media-gallery data-layout=\"{{#if layout}}{{layout}}{{else}}grid{{/if}}\" class=\"block w-full space-y-6\">\n  <div class=\"space-y-1.5 empty:hidden\">\n    {{#if gallery_title}}<h3 class=\"text-xl sm:text-2xl font-bold tracking-tight text-slate-900 dark:text-white\">{{gallery_title}}</h3>{{/if}}\n    {{#if gallery_subtitle}}<p class=\"text-sm text-slate-500 dark:text-slate-400\">{{gallery_subtitle}}</p>{{/if}}\n  </div>\n  <div class=\"univers-gallery-grid\">\n    {{#each items}}\n    <figure class=\"group p-3.5 rounded-xl univers-card-surface border univers-border-base univers-border-accent-hover flex flex-col space-y-3\">\n      <div class=\"univers-gallery-frame h-44 rounded-lg bg-slate-50 dark:bg-slate-950 border border-slate-200/60 dark:border-slate-800/80 flex items-center justify-center p-4 relative overflow-hidden\">\n        <img src=\"{{url}}\" alt=\"{{title}}\" class=\"max-h-full max-w-full object-contain transition-transform duration-300 group-hover:scale-105\" />\n        {{#if mime_type}}<span class=\"absolute top-2.5 right-2.5 px-2 py-0.5 rounded-md text-[10px] font-mono font-bold univers-badge-accent backdrop-blur-xs\">{{mime_type}}</span>{{/if}}\n      </div>\n      <figcaption class=\"flex items-center justify-between gap-2 px-1\">\n        <div class=\"text-xs font-bold text-slate-800 dark:text-slate-100 truncate univers-group-accent transition\" title=\"{{title}}\">{{title}}</div>\n        {{#if folder}}<span class=\"px-2 py-0.5 rounded-md text-[10px] font-mono bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 shrink-0\">{{folder}}</span>{{/if}}\n      </figcaption>\n    </figure>\n    {{/each}}\n  </div>\n</univers-media-gallery>"},{"slug":"univers-article-view","name":"文章正文阅读器 (Univers Article View)","title":"文章正文阅读器 (Univers Article View)","category":"content","icon":"article","slots":["main"],"description":"文章详情页主阅读器，承接长文正文与阅读进度元信息","summary":"文章详情页主阅读容器，自动承接 {{content_html}}、阅读进度条、元信息控制与多语言互译切换。","ui_schema":[{"key":"show_meta_bar","label":"显示文章元信息栏","type":"boolean","widget":"switch","default":true},{"key":"back_link_text","label":"返回链接文案 (留空则隐藏)","type":"text","default":"返回时间线归档"},{"key":"back_link_url","label":"返回链接地址","type":"text","default":"/archive"}],"default_props":{"show_meta_bar":true,"back_link_text":"返回时间线归档","back_link_url":"/archive","title":"欢迎使用 Walnut：5 分钟上手指南","category":"指南","published_date":"2026-11-18","reading_time":"3","author":"Admin","description":"从零了解文章排版、Markdown 容器、TOC 目录与双向知识内链。","translations":[{"locale":"zh-CN","url":"/hello-walnut","isCurrent":true},{"locale":"en-US","url":"/hello-walnut-en","isCurrent":false}],"content_html":"<p class=\"text-slate-700 dark:text-slate-300\">这是文章正文阅读器的实时预览内容。实际发布后将由系统自动注入渲染后的 Markdown 正文 HTML。</p>"},"template_html":"<univers-article-view class=\"block\">\n  <div id=\"edge-reading-progress\" data-edge-reading-progress class=\"univers-progress-bar fixed top-0 left-0 h-1 z-50 transition-all duration-75\" style=\"width: 0%;\"></div>\n  <article class=\"max-w-3xl mx-auto space-y-8 text-slate-900 dark:text-slate-100\">\n    <header class=\"space-y-4 border-b univers-border-base pb-7\">\n      {{#if show_meta_bar}}\n      <div class=\"flex flex-wrap items-center justify-between gap-2\">\n        {{#if back_link_text}}<a href=\"{{back_link_url}}\" class=\"inline-flex items-center gap-1.5 text-xs font-bold univers-accent-text hover:underline\">&larr; {{back_link_text}}</a>{{/if}}\n        <div class=\"flex flex-wrap items-center gap-2 text-xs font-mono text-slate-500 dark:text-slate-400\">\n          {{#if category}}<span class=\"px-2.5 py-0.5 rounded-full univers-badge-accent font-bold\">{{category}}</span>{{else}}{{#if page.category}}<span class=\"px-2.5 py-0.5 rounded-full univers-badge-accent font-bold\">{{page.category}}</span>{{/if}}{{/if}}\n          <span>{{#if page.published_date}}{{page.published_date}}{{else}}{{published_date}}{{/if}}</span>\n          <span>· {{#if page.reading_time}}{{page.reading_time}}{{else}}{{reading_time}}{{/if}} {{#if i18n.reading_unit}}{{i18n.reading_unit}}{{else}}min read{{/if}}</span>\n          <span>· {{#if page.author}}{{page.author}}{{else}}{{author}}{{/if}}</span>\n        </div>\n      </div>\n      {{/if}}\n      {{#if translations}}\n      <div class=\"walnut-translation-links flex flex-wrap gap-1.5 text-xs font-mono pt-1\">\n        {{#each translations}}\n        <a href=\"{{url}}\" class=\"px-2.5 py-0.5 rounded-lg transition {{#if isCurrent}}univers-pill-active font-bold{{else}}bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 hover:bg-slate-200/80 dark:hover:bg-slate-700{{/if}}\">{{locale}}</a>\n        {{/each}}\n      </div>\n      {{/if}}\n      <h1 class=\"text-2xl sm:text-4xl font-bold tracking-tight text-slate-900 dark:text-white leading-tight\">\n        {{#if page.title}}{{page.title}}{{else}}{{title}}{{/if}}\n      </h1>\n      {{#if summary}}<p class=\"text-base text-slate-600 dark:text-slate-300 leading-relaxed\">{{summary}}</p>{{else}}{{#if description}}<p class=\"text-base text-slate-600 dark:text-slate-300 leading-relaxed\">{{description}}</p>{{else}}{{#if page.summary}}<p class=\"text-base text-slate-600 dark:text-slate-300 leading-relaxed\">{{page.summary}}</p>{{else}}{{#if page.description}}<p class=\"text-base text-slate-600 dark:text-slate-300 leading-relaxed\">{{page.description}}</p>{{/if}}{{/if}}{{/if}}{{/if}}\n    </header>\n    <div class=\"walnut-article-content prose dark:prose-invert max-w-none text-slate-800 dark:text-slate-200 leading-relaxed space-y-6\">\n      {{{content_html}}}\n    </div>\n  </article>\n</univers-article-view>"},{"slug":"univers-toc-sidebar","name":"文章目录与反向双链 (Univers TOC Sidebar)","title":"文章目录与反向双链 (Univers TOC Sidebar)","category":"navigation","icon":"toc","slots":["sidebar","main"],"description":"目录与双链导航卡，放 sidebar 吸顶，放 main 可折叠","summary":"零参数槽位自适应：在 sidebar 吸顶显示目录与双链，在 main 自动切换为可折叠文首目录盒。","ui_schema":[{"key":"toc_title","label":"目录标题","type":"text","default":"本文目录大纲"},{"key":"backlinks_title","label":"反向双链标题","type":"text","default":"双向链接引用"}],"default_props":{"toc_title":"本文目录","backlinks_title":"反向双链","backlinks":[{"title":"构建我的数字花园工作流","slug":"building-digital-garden","url":"/building-digital-garden"}]},"template_html":"<univers-toc-sidebar class=\"block space-y-6\">\n  <details open class=\"univers-toc-section border-l border-slate-200 dark:border-slate-800 pl-4 space-y-2.5\">\n    <summary class=\"univers-toc-summary flex items-center justify-between gap-2 cursor-pointer text-xs font-bold uppercase tracking-wider text-slate-900 dark:text-white\">\n      <span>{{#if toc_title}}{{toc_title}}{{else}}{{#if i18n.outline_title}}{{i18n.outline_title}}{{else}}On This Page{{/if}}{{/if}}</span>\n      <span class=\"univers-toc-chevron text-slate-400 font-mono text-xs\">+</span>\n    </summary>\n    <nav class=\"univers-toc-list space-y-1 text-xs text-slate-600 dark:text-slate-400\">\n      <div class=\"text-xs text-slate-400 py-1\">{{#if i18n.loading_outline}}{{i18n.loading_outline}}{{else}}Loading outline...{{/if}}</div>\n    </nav>\n  </details>\n  {{#if backlinks}}\n  <div class=\"univers-toc-section border-l border-slate-200 dark:border-slate-800 pl-4 space-y-2.5\">\n    <h3 class=\"text-xs font-bold uppercase tracking-wider text-slate-900 dark:text-white\">{{#if backlinks_title}}{{backlinks_title}}{{else}}{{#if i18n.backlinks_title}}{{i18n.backlinks_title}}{{else}}Backlinks{{/if}}{{/if}}</h3>\n    <div class=\"space-y-1.5\">\n      {{#each backlinks}}\n      <a href=\"{{#if url}}{{url}}{{else}}/{{slug}}{{/if}}\" class=\"block py-1.5 px-2 -mx-2 rounded-lg hover:bg-slate-100/80 dark:hover:bg-slate-800/60 transition group\">\n        <div class=\"text-xs font-semibold text-slate-700 dark:text-slate-300 univers-group-accent transition-colors\">{{title}}</div>\n        <div class=\"text-[11px] font-mono text-slate-400 dark:text-slate-500 mt-0.5\">&larr; {{#if url}}{{url}}{{else}}/{{slug}}{{/if}}</div>\n      </a>\n      {{/each}}\n    </div>\n  </div>\n  {{/if}}\n</univers-toc-sidebar>"},{"slug":"univers-lead-form","name":"通用联系与转化表单 (Univers Lead Form)","title":"通用联系与转化表单 (Univers Lead Form)","category":"form","icon":"mail","slots":["main"],"description":"通用线索与联系表单，体量较大，适合页面中下部转化","summary":"通用联系与线索提交表单，支持 split / compact 布局与 contrast / soft 视觉基调，可选左侧要点列表。","ui_schema":[{"key":"layout","label":"表单布局","widget":"select","type":"select","options":[{"label":"Split (左说明 + 右表单)","value":"split"},{"label":"Compact (居中单栏)","value":"compact"}],"default":"split"},{"key":"tone","label":"视觉基调","widget":"select","type":"select","options":[{"label":"Soft (柔和浅底，跟随明暗)","value":"soft"},{"label":"Contrast (高对比深色)","value":"contrast"}],"default":"soft"},{"key":"badge_text","label":"顶部标签 (留空则隐藏)","type":"text","default":"CONTACT"},{"key":"title","label":"表单标题","type":"text","default":"保持联系或提交反馈"},{"key":"subtitle","label":"副标题描述 (留空则隐藏)","type":"textarea","default":"填写您的称呼、邮箱与留言内容，提交后可通过后台 Webhook 自动转发至指定通道。"},{"key":"button_text","label":"提交按钮文案","type":"text","default":"发送消息"},{"key":"form_action","label":"提交目标路径","type":"text","default":"/api/forms/submit/contact"},{"key":"highlights","label":"左侧要点列表 (留空则隐藏)","type":"json","widget":"list","item_schema":[{"key":"text","label":"要点文案","type":"text"}],"default":[]}],"default_props":{"layout":"split","tone":"soft","badge_text":"CONTACT","title":"保持联系","subtitle":"欢迎就项目合作、技术交流或文章想法来信，通常会在一至两个工作日内回复。","button_text":"发送消息","form_action":"/api/forms/submit/contact","highlights":[]},"template_html":"<univers-convert-block class=\"univers-lead-form block\" data-layout=\"{{#if layout}}{{layout}}{{else}}split{{/if}}\" data-tone=\"{{#if tone}}{{tone}}{{else}}soft{{/if}}\" data-action=\"api\" data-target=\"{{#if form_action}}{{form_action}}{{else}}/api/forms/submit/contact{{/if}}\">\n  <div class=\"univers-lead-surface rounded-2xl p-6 sm:p-10\">\n    <div class=\"univers-lead-grid grid grid-cols-1 lg:grid-cols-12 gap-8 items-start\">\n      <div class=\"lg:col-span-5 space-y-4\">\n        {{#if badge_text}}<span class=\"inline-block px-2.5 py-0.5 rounded-full text-[11px] font-mono font-bold univers-badge-accent\">{{badge_text}}</span>{{/if}}\n        {{#if title}}<h2 class=\"text-2xl sm:text-3xl font-bold tracking-tight leading-tight\">{{title}}</h2>{{/if}}\n        {{#if subtitle}}<p class=\"univers-lead-muted text-sm text-slate-600 dark:text-slate-400 leading-relaxed\">{{subtitle}}</p>{{/if}}\n        {{#if highlights}}\n        <ul class=\"univers-lead-highlights space-y-2 pt-2 text-xs text-slate-600 dark:text-slate-300\">\n          {{#each highlights}}\n          <li class=\"flex items-center gap-2\"><span class=\"w-1.5 h-1.5 rounded-full univers-accent-dot shrink-0\"></span><span>{{text}}</span></li>\n          {{/each}}\n        </ul>\n        {{/if}}\n      </div>\n      <div class=\"lg:col-span-7\">\n        <form class=\"univers-convert-form space-y-4\">\n          <input type=\"text\" name=\"_honeypot\" class=\"hidden\" tabindex=\"-1\" autocomplete=\"off\" aria-hidden=\"true\" />\n          <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n            <div class=\"space-y-1.5\">\n              <label class=\"univers-lead-muted block text-[11px] font-mono text-slate-500 dark:text-slate-400 uppercase tracking-wider\">{{#if name_label}}{{name_label}}{{else}}{{#if i18n.form_name}}{{i18n.form_name}}{{else}}Name{{/if}}{{/if}}</label>\n              <input type=\"text\" name=\"name\" placeholder=\"{{#if name_placeholder}}{{name_placeholder}}{{else}}{{#if i18n.form_name_placeholder}}{{i18n.form_name_placeholder}}{{else}}Your name{{/if}}{{/if}}\" class=\"univers-convert-name univers-lead-input w-full px-3.5 py-2.5 rounded-lg border text-sm outline-none\" />\n            </div>\n            <div class=\"space-y-1.5\">\n              <label class=\"univers-lead-muted block text-[11px] font-mono text-slate-500 dark:text-slate-400 uppercase tracking-wider\">{{#if email_label}}{{email_label}}{{else}}{{#if i18n.form_email}}{{i18n.form_email}}{{else}}Email *{{/if}}{{/if}}</label>\n              <input type=\"email\" name=\"email\" required placeholder=\"{{#if email_placeholder}}{{email_placeholder}}{{else}}you@example.com{{/if}}\" class=\"univers-convert-input univers-lead-input w-full px-3.5 py-2.5 rounded-lg border text-sm outline-none\" />\n            </div>\n          </div>\n          <div class=\"space-y-1.5\">\n            <label class=\"univers-lead-muted block text-[11px] font-mono text-slate-500 dark:text-slate-400 uppercase tracking-wider\">{{#if message_label}}{{message_label}}{{else}}{{#if i18n.form_message}}{{i18n.form_message}}{{else}}Message{{/if}}{{/if}}</label>\n            <textarea name=\"message\" rows=\"3\" placeholder=\"{{#if message_placeholder}}{{message_placeholder}}{{else}}{{#if i18n.form_message_placeholder}}{{i18n.form_message_placeholder}}{{else}}Share your thoughts or inquiry...{{/if}}{{/if}}\" class=\"univers-convert-message univers-lead-input w-full px-3.5 py-2.5 rounded-lg border text-sm outline-none resize-y\"></textarea>\n          </div>\n          <div class=\"flex justify-end pt-1\">\n            <button type=\"submit\" class=\"w-full sm:w-auto px-6 py-2.5 rounded-lg text-xs font-bold univers-btn-primary cursor-pointer\">{{#if button_text}}{{button_text}}{{else}}{{#if i18n.form_submit}}{{i18n.form_submit}}{{else}}Send Message{{/if}}{{/if}} &rarr;</button>\n          </div>\n        </form>\n      </div>\n    </div>\n  </div>\n</univers-convert-block>"},{"slug":"univers-footer","name":"页脚版权栏 (Univers Footer)","title":"页脚版权栏 (Univers Footer)","category":"navigation","icon":"bottom_navigation","slots":["footer"],"description":"全局底部版权页脚，限放 footer 槽位，含链接与署名","summary":"支持 simple / rich 两种页脚形态，原生消费 tagline、footer_links 与 powered_by 契约。","ui_schema":[{"key":"layout","label":"页脚形态","widget":"select","type":"select","options":[{"label":"Simple (精致单行)","value":"simple"},{"label":"Rich (品牌标语 + 链接区)","value":"rich"}],"default":"simple"},{"key":"brand_name","label":"品牌名称 (留空取站点名)","type":"text","default":""},{"key":"tagline","label":"品牌标语 (Rich 模式展示)","type":"text","default":"边缘原生内容与模块化页面装配起点"},{"key":"copyright_text","label":"版权文案 (留空取默认)","type":"text","default":""},{"key":"footer_links","label":"底部导航链接","type":"json","widget":"list","item_schema":[{"key":"text","label":"文字","type":"text"},{"key":"url","label":"链接","type":"text"}],"default":[]}],"default_props":{"layout":"simple","brand_name":"","tagline":"","copyright_text":"","footer_links":[]},"template_html":"<univers-footer data-layout=\"{{#if layout}}{{layout}}{{else}}simple{{/if}}\" class=\"block w-full\">\n  <div class=\"max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-5 text-xs text-slate-500 dark:text-slate-400\">\n    <div class=\"univers-footer-top flex flex-col sm:flex-row sm:items-center justify-between gap-4\">\n      <div class=\"space-y-1\">\n        <div class=\"font-bold text-sm text-slate-900 dark:text-white\">{{#if brand_name}}{{brand_name}}{{else}}{{site.name}}{{/if}}</div>\n        {{#if tagline}}<p class=\"univers-footer-tagline text-xs text-slate-500 dark:text-slate-400 max-w-md\">{{tagline}}</p>{{/if}}\n      </div>\n      {{#if footer_links}}\n      <nav class=\"flex flex-wrap items-center gap-5 font-medium\">\n        {{#each footer_links}}\n        <a href=\"{{#if url}}{{url}}{{else}}{{href}}{{/if}}\" class=\"univers-link-accent\">{{#if text}}{{text}}{{else}}{{label}}{{/if}}</a>\n        {{/each}}\n      </nav>\n      {{/if}}\n    </div>\n    <div class=\"univers-footer-bottom pt-4 border-t border-slate-200/70 dark:border-slate-800/80 flex flex-col sm:flex-row sm:items-center justify-between gap-2\">\n      <span class=\"font-mono text-[11px]\">{{#if copyright_text}}{{copyright_text}}{{else}}{{site.copyright}}{{/if}}</span>\n      {{#if powered_by.enabled}}\n      <div class=\"univers-footer-whitelabel font-mono text-[11px] text-slate-400 dark:text-slate-500 sm:text-right\">\n        <a href=\"{{powered_by.url}}\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"univers-link-accent\">{{powered_by.label}}</a>\n      </div>\n      {{/if}}\n    </div>\n  </div>\n</univers-footer>"},{"slug":"univers-article-archive","name":"文章归档列表 (Univers Article Archive)","title":"文章归档列表 (Univers Article Archive)","category":"content","icon":"library_books","slots":["main"],"version":"1.2.0","description":"文章时间线归档列表，适合博客目录与分类文章聚合页","summary":"支持 clean / card / compact 三档展示风格，兼容 published_date 与 published_at。","ui_schema":[{"key":"title","label":"归档标题 (留空则隐藏)","type":"text","default":"精选文章"},{"key":"subtitle","label":"副标题 (留空则隐藏)","type":"text","default":""},{"key":"variant","label":"展示风格","widget":"select","type":"select","options":[{"label":"Clean (极简无边框文字流)","value":"clean"},{"label":"Card (微边框卡片)","value":"card"},{"label":"Compact (极简单行索引)","value":"compact"}],"default":"clean"},{"key":"page_size","label":"每页条数","type":"number","default":12},{"key":"items","label":"数据源","type":"json","widget":"list","item_schema":[{"key":"title","label":"文章标题","type":"text"},{"key":"slug","label":"路径 (Slug)","type":"text"},{"key":"summary","label":"文章摘要","type":"textarea"},{"key":"folder","label":"目录","type":"text"},{"key":"locale","label":"语言","type":"text"},{"key":"published_date","label":"发布日期","type":"text"}],"default":"@api:articles:limit=12"}],"default_props":{"title":"精选文章","subtitle":"","variant":"clean","page_size":12,"items":[{"title":"欢迎使用 Walnut：5 分钟上手指南","slug":"hello-walnut","folder":"guide","locale":"zh-CN","summary":"快速了解文章撰写、Markdown 扩展容器与双向内链。","published_date":"2026-11-18"},{"title":"页面装配、微内容与 @api: 数据直连","slug":"architecture-and-slots","folder":"guide","locale":"zh-CN","summary":"说明可视化槽位装配、@api: 数据绑定与多站点隔离机制。","published_date":"2026-11-18"}]},"template_html":"<univers-article-archive class=\"univers-archive block space-y-5\" data-variant=\"{{#if variant}}{{variant}}{{else}}clean{{/if}}\" data-page-size=\"{{#if page_size}}{{page_size}}{{else}}12{{/if}}\">\n  <div class=\"flex flex-col sm:flex-row sm:items-end justify-between gap-3 border-b univers-border-base pb-3.5 empty:hidden\">\n    <div class=\"space-y-1 empty:hidden\">\n      {{#if title}}<h2 class=\"text-xl sm:text-2xl font-bold tracking-tight text-slate-900 dark:text-white\">{{title}}</h2>{{/if}}\n      {{#if subtitle}}<p class=\"text-sm text-slate-500 dark:text-slate-400\">{{subtitle}}</p>{{/if}}\n    </div>\n    <div class=\"univers-archive-filters flex flex-wrap items-center gap-1.5 text-xs font-bold empty:hidden\"></div>\n  </div>\n  <div class=\"univers-archive-list grid grid-cols-1 md:grid-cols-2 gap-5\">\n    {{#each items}}\n    <a href=\"{{#if url}}{{url}}{{else}}/{{slug}}{{/if}}\" class=\"univers-archive-item group p-5 rounded-xl univers-card-surface border univers-border-base univers-border-accent-hover flex flex-col justify-between space-y-2.5\" data-folder=\"{{folder}}\" data-locale=\"{{locale}}\">\n      <div class=\"univers-archive-body space-y-2\">\n        <div class=\"flex items-center gap-2 text-[11px] font-mono empty:hidden\">{{#if folder}}<span class=\"univers-archive-folder px-2 py-0.5 rounded-md univers-badge-accent font-bold\">{{folder}}</span>{{/if}}{{#if locale}}<span class=\"univers-archive-locale px-2 py-0.5 rounded-md bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400\">{{locale}}</span>{{/if}}</div>\n        {{#if title}}<h3 class=\"univers-archive-title text-base sm:text-lg font-bold text-slate-900 dark:text-white univers-group-accent transition-colors\">{{title}}</h3>{{/if}}\n        {{#if summary}}<p class=\"univers-archive-summary text-sm text-slate-600 dark:text-slate-400 line-clamp-2 leading-relaxed\">{{summary}}</p>{{/if}}\n      </div>\n      <div class=\"flex items-center justify-between text-[11px] font-mono text-slate-400 shrink-0 gap-3 empty:hidden\">{{#if published_date}}<span>{{published_date}}</span>{{else}}{{#if published_at}}<span>{{published_at}}</span>{{/if}}{{/if}}{{#if slug}}<span class=\"univers-archive-slug\">/{{slug}}</span>{{/if}}</div>\n    </a>\n    {{/each}}\n  </div>\n  <div class=\"univers-archive-pager flex items-center justify-center gap-2 pt-2 empty:hidden\"></div>\n</univers-article-archive>"},{"slug":"univers-split-feature","name":"左右图文穿插 (Univers Split Feature)","title":"左右图文穿插 (Univers Split Feature)","category":"layout","icon":"view_sidebar","slots":["main"],"description":"左右图文穿插区块，适合细节介绍，多块可镜像交替","summary":"支持 boxed / plain 两种容器风格与镜像翻转；无配图时自动退化为聚焦单栏。","ui_schema":[{"key":"variant","label":"容器风格","widget":"select","type":"select","options":[{"label":"Boxed (柔和边框卡片)","value":"boxed"},{"label":"Plain (无框自然穿插)","value":"plain"}],"default":"boxed"},{"key":"badge","label":"标签徽章 (留空则隐藏)","type":"text","default":"ARCHITECTURE"},{"key":"title","label":"主标题","type":"text","default":"契约驱动的主题与内容彻底解耦"},{"key":"description","label":"说明正文","type":"textarea","default":"主题仅声明插槽与视觉契约，业务数据通过页面级 @api: 协议自由装配，更换主题零数据迁移成本。"},{"key":"image_url","label":"配图地址 (留空则自动单栏)","type":"image","default":""},{"key":"cta_text","label":"按钮文案 (留空则隐藏)","type":"text","default":"浏览项目展厅"},{"key":"cta_url","label":"按钮链接","type":"text","default":"/projects"},{"key":"reverse","label":"左右镜像反转","type":"boolean","widget":"switch","default":false}],"default_props":{"variant":"boxed","badge":"ARCHITECTURE","title":"契约驱动的主题与内容彻底解耦","description":"主题仅声明插槽与视觉契约，业务数据通过页面级 @api: 协议自由装配，更换主题零数据迁移成本。","image_url":"","cta_text":"浏览项目展厅","cta_url":"/projects","reverse":false},"template_html":"<section class=\"univers-split-feature block\" data-variant=\"{{#if variant}}{{variant}}{{else}}boxed{{/if}}\">\n  <div class=\"univers-split-surface univers-muted-surface grid grid-cols-1 {{#if image_url}}lg:grid-cols-2{{/if}} gap-8 lg:gap-10 items-center p-6 sm:p-10 rounded-2xl border univers-border-base\">\n    <div class=\"space-y-4 {{#if reverse}}lg:order-2{{/if}}\">\n      {{#if badge}}<span class=\"inline-block px-3 py-0.5 rounded-full text-[11px] font-mono font-bold univers-badge-accent\">{{badge}}</span>{{/if}}\n      {{#if title}}<h2 class=\"text-2xl sm:text-3xl font-bold tracking-tight text-slate-900 dark:text-white leading-tight\">{{title}}</h2>{{/if}}\n      {{#if description}}<p class=\"text-sm sm:text-base text-slate-600 dark:text-slate-300 leading-relaxed\">{{description}}</p>{{/if}}\n      {{#if cta_text}}<div class=\"pt-1\"><a href=\"{{cta_url}}\" class=\"inline-flex items-center gap-1.5 px-5 py-2.5 rounded-lg text-xs font-bold univers-btn-primary\">{{cta_text}} &rarr;</a></div>{{/if}}\n    </div>\n    {{#if image_url}}\n    <div class=\"{{#if reverse}}lg:order-1{{/if}} flex items-center justify-center p-4 rounded-xl bg-white dark:bg-slate-950 border border-slate-200/70 dark:border-slate-800\">\n      <img src=\"{{image_url}}\" alt=\"{{title}}\" class=\"max-h-60 w-auto object-contain rounded-lg\" />\n    </div>\n    {{/if}}\n  </div>\n</section>"},{"slug":"univers-faq-accordion","name":"折叠问答 (Univers FAQ Accordion)","title":"折叠问答 (Univers FAQ Accordion)","category":"content","icon":"quiz","slots":["main"],"description":"折叠常见问题列表，适合 Hero、方案对比或表单衔接处","summary":"原生零 JS 折叠问答列表，支持 stack（居中堆叠）与 split（左标题右问答）双布局。","ui_schema":[{"key":"layout","label":"排版布局","widget":"select","type":"select","options":[{"label":"Stack (居中堆叠)","value":"stack"},{"label":"Split (左说明 + 右列表)","value":"split"}],"default":"stack"},{"key":"title","label":"区块标题","type":"text","default":"常见问题解答"},{"key":"subtitle","label":"副标题描述 (留空则隐藏)","type":"text","default":"关于页面装配、主题切换与数据结构扩展的高频说明"},{"key":"items","label":"问答条目","type":"json","widget":"list","item_schema":[{"key":"title","label":"问题","type":"text"},{"key":"summary","label":"回答","type":"textarea"}],"default":[{"title":"如何通过 Schema 扩展作品集、工具目录或书影音清单？","summary":"在后台「数据集与 Schema」新建字段定义并录入条目，随后在任意页面将展示组件数据源绑定为 @api:dataset:collection=你的标识 即可实时渲染。"},{"title":"更换主题会丢失文章或页面数据吗？","summary":"不会。所有正文、微内容与数据集独立存储于 D1 数据库，更换主题仅切换布局骨架与组件样式契约。"}]}],"default_props":{"layout":"stack","title":"常见问题解答","subtitle":"关于页面装配、主题切换与数据结构扩展的高频说明","items":[{"title":"如何通过 Schema 扩展作品集、工具目录或书影音清单？","summary":"在后台「数据集与 Schema」新建字段定义并录入条目，随后在任意页面将展示组件数据源绑定为 @api:dataset:collection=你的标识 即可实时渲染。"},{"title":"更换主题会丢失文章或页面数据吗？","summary":"不会。所有正文、微内容与数据集独立存储于 D1 数据库，更换主题仅切换布局骨架与组件样式契约。"}]},"template_html":"<section class=\"univers-faq block\" data-layout=\"{{#if layout}}{{layout}}{{else}}stack{{/if}}\">\n  <div class=\"univers-faq-grid space-y-6\">\n    <div class=\"univers-faq-header text-center space-y-2 empty:hidden\">\n      {{#if title}}<h2 class=\"text-2xl sm:text-3xl font-bold tracking-tight text-slate-900 dark:text-white\">{{title}}</h2>{{/if}}\n      {{#if subtitle}}<p class=\"text-sm text-slate-500 dark:text-slate-400 leading-relaxed\">{{subtitle}}</p>{{/if}}\n    </div>\n    <div class=\"space-y-3\">\n      {{#each items}}\n      <details class=\"group rounded-xl univers-card-surface border univers-border-base univers-border-accent-hover px-5 py-4\">\n        <summary class=\"flex items-center justify-between gap-4 cursor-pointer list-none font-bold text-sm text-slate-900 dark:text-white\">\n          <span>{{#if question}}{{question}}{{else}}{{title}}{{/if}}</span>\n          <span class=\"univers-accent-text font-mono text-base transition-transform group-open:rotate-45 shrink-0\">+</span>\n        </summary>\n        <div class=\"pt-3 mt-3 border-t border-slate-100 dark:border-slate-800/80 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n          {{#if answer}}{{answer}}{{else}}{{summary}}{{/if}}\n        </div>\n      </details>\n      {{/each}}\n    </div>\n  </div>\n</section>"},{"slug":"univers-cta-banner","name":"行动号召横幅 (Univers CTA Banner)","title":"行动号召横幅 (Univers CTA Banner)","category":"layout","icon":"ads_click","slots":["main"],"description":"全宽转化号召横幅，视觉醒目，适合页面底部收口引导","summary":"支持 contrast / soft / minimal 三种基调的轻量转化横幅。","ui_schema":[{"key":"tone","label":"视觉基调","widget":"select","type":"select","options":[{"label":"Soft (跟随主色的柔和浅底)","value":"soft"},{"label":"Contrast (高对比深色横幅)","value":"contrast"},{"label":"Minimal (极简细边框)","value":"minimal"}],"default":"soft"},{"key":"badge","label":"顶部徽章 (留空则隐藏)","type":"text","default":"GET STARTED"},{"key":"title","label":"横幅标题","type":"text","default":"开始定制你的边缘内容站点"},{"key":"subtitle","label":"副标题描述 (留空则隐藏)","type":"text","default":"在控制台自由编排页面槽位、调整站点双色主色或一键清理示例指南内容。"},{"key":"primary_text","label":"主按钮文案 (留空则隐藏)","type":"text","default":"进入控制台"},{"key":"primary_url","label":"主按钮链接","type":"text","default":"/admin"},{"key":"secondary_text","label":"次按钮文案 (留空则隐藏)","type":"text","default":"阅读上手指南"},{"key":"secondary_url","label":"次按钮链接","type":"text","default":"/hello-walnut"}],"default_props":{"tone":"soft","badge":"GET STARTED","title":"开始定制你的边缘内容站点","subtitle":"在控制台自由编排页面槽位、调整站点双色主色或一键清理示例指南内容。","primary_text":"进入控制台","primary_url":"/admin","secondary_text":"阅读上手指南","secondary_url":"/hello-walnut"},"template_html":"<section class=\"univers-cta-banner block\" data-tone=\"{{#if tone}}{{tone}}{{else}}soft{{/if}}\">\n  <div class=\"univers-cta-surface rounded-2xl p-7 sm:p-10\">\n    <div class=\"flex flex-col lg:flex-row lg:items-center justify-between gap-6\">\n      <div class=\"space-y-2 max-w-2xl\">\n        {{#if badge}}<span class=\"inline-block px-2.5 py-0.5 rounded-full text-[10px] font-mono font-bold uppercase tracking-wider univers-badge-accent\">{{badge}}</span>{{/if}}\n        {{#if title}}<h2 class=\"text-2xl sm:text-3xl font-bold tracking-tight\">{{title}}</h2>{{/if}}\n        {{#if subtitle}}<p class=\"text-sm opacity-80 leading-relaxed\">{{subtitle}}</p>{{/if}}\n      </div>\n      <div class=\"flex flex-wrap items-center gap-3 shrink-0 empty:hidden\">\n        {{#if primary_text}}<a href=\"{{primary_url}}\" class=\"px-5 py-2.5 rounded-lg text-xs font-bold univers-btn-primary\">{{primary_text}} &rarr;</a>{{/if}}\n        {{#if secondary_text}}<a href=\"{{secondary_url}}\" class=\"px-5 py-2.5 rounded-lg text-xs font-bold univers-btn-soft\">{{secondary_text}}</a>{{/if}}\n      </div>\n    </div>\n  </div>\n</section>"},{"slug":"univers-breadcrumb-pager","name":"面包屑与上下篇导航 (Univers Breadcrumb Pager)","title":"面包屑与上下篇导航 (Univers Breadcrumb Pager)","category":"navigation","icon":"linear_scale","slots":["main"],"description":"面包屑与上下篇翻页条，适合文章或嵌套子页面首尾","summary":"结构化面包屑路