/span></a>{{/if}}{{#if next_url}}<a href=\"{{next_url}}\" class=\"p-3.5 rounded-xl univers-muted-surface border univers-border-base univers-border-accent-hover flex flex-col gap-1 sm:text-right sm:col-start-2\"><span class=\"text-[10px] font-mono uppercase text-slate-400\">{{#if next_label}}{{next_label}}{{else}}{{#if i18n.next_label}}{{i18n.next_label}}{{else}}Next{{/if}}{{/if}} &rarr;</span><span class=\"text-xs font-bold text-slate-800 dark:text-slate-200 truncate\">{{next_title}}</span></a>{{/if}}</div>\n</nav>"},{"slug":"univers-profile-card","name":"作者与站点名片 (Univers Profile Card)","title":"作者与站点名片 (Univers Profile Card)","category":"layout","icon":"badge","slots":["sidebar","main"],"description":"作者与站点名片卡，侧栏呈竖排，主区自动展为横排条","summary":"容器自适应名片：在 sidebar 呈竖版名片，在宽 main 槽位自动展开为横版名片条。","ui_schema":[{"key":"avatar_url","label":"头像图片地址 (留空则隐藏)","type":"image","default":""},{"key":"name","label":"名称","type":"text","default":""},{"key":"role","label":"头衔 / 副标题 (留空则隐藏)","type":"text","default":""},{"key":"status_text","label":"当前状态胶囊 (留空则隐藏)","type":"text","default":""},{"key":"bio","label":"简介描述 (留空则隐藏)","type":"textarea","default":""},{"key":"links","label":"相关链接","type":"json","widget":"list","item_schema":[{"key":"text","label":"名称","type":"text"},{"key":"url","label":"链接","type":"text"}],"default":[]}],"default_props":{"avatar_url":"","name":"","role":"","bio":"","status_text":"","links":[]},"template_html":"<univers-profile-card class=\"block p-5 rounded-xl univers-card-surface border univers-border-base\">\n  <div class=\"univers-profile-body\">\n    <div class=\"space-y-3 min-w-0\">\n      <div class=\"flex items-center gap-3.5 empty:hidden\">\n        {{#if avatar_url}}<img src=\"{{avatar_url}}\" alt=\"{{name}}\" class=\"w-12 h-12 rounded-lg object-cover border border-slate-200/80 dark:border-slate-700 shrink-0\" />{{/if}}\n        <div class=\"min-w-0 space-y-0.5 empty:hidden\">\n          {{#if name}}<h3 class=\"text-base font-bold text-slate-900 dark:text-white truncate\">{{name}}</h3>{{/if}}\n          {{#if role}}<p class=\"text-xs text-slate-500 dark:text-slate-400 truncate\">{{role}}</p>{{/if}}\n        </div>\n      </div>\n      {{#if status_text}}<div class=\"inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-[11px] font-mono univers-badge-accent\"><span class=\"w-1.5 h-1.5 rounded-full univers-accent-dot\"></span><span>{{status_text}}</span></div>{{/if}}\n      {{#if bio}}<p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">{{bio}}</p>{{/if}}\n    </div>\n    {{#if links}}<div class=\"univers-profile-links pt-3 border-t border-slate-100 dark:border-slate-800/80 flex flex-wrap gap-2 empty:hidden\">{{#each links}}<a href=\"{{#if url}}{{url}}{{else}}{{href}}{{/if}}\" class=\"px-2.5 py-1 rounded-lg text-xs font-medium bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-200 univers-link-accent\">{{#if text}}{{text}}{{else}}{{label}}{{/if}}</a>{{/each}}</div>{{/if}}\n  </div>\n</univers-profile-card>"},{"slug":"univers-timeline","name":"垂直混排时间线 (Univers Timeline)","title":"垂直混排时间线 (Univers Timeline)","category":"content","icon":"timeline","slots":["main"],"description":"跨类型聚合时间线，适合混排文章、微内容与项目记录","summary":"兼容 @api:feed: 聚合输出，支持 comfortable / compact 两种信息密度。","ui_schema":[{"key":"heading","label":"时间线标题 (留空则隐藏)","type":"text","default":"内容时间线"},{"key":"subheading","label":"副标题 (留空则隐藏)","type":"text","default":"聚合文章、微内容与项目记录"},{"key":"density","label":"时间线密度","widget":"select","type":"select","options":[{"label":"Comfortable (展示摘要与微内容)","value":"comfortable"},{"label":"Compact (紧凑日志视图)","value":"compact"}],"default":"comfortable"},{"key":"read_more_text","label":"阅读链接文案","type":"text","default":"阅读全文"},{"key":"items","label":"数据源 (@api:feed:...)","type":"json","widget":"list","item_schema":[{"key":"date","label":"日期","type":"text"},{"key":"type_label","label":"类型标签","type":"text"},{"key":"badge","label":"徽章","type":"text"},{"key":"title","label":"标题 (可选)","type":"text"},{"key":"summary","label":"内容摘要","type":"textarea"},{"key":"url","label":"详情链接 (可选)","type":"text"}],"default":"@api:feed:types=article,micro&limit=20"}],"default_props":{"heading":"内容时间线","subheading":"聚合文章、微内容与项目记录","density":"comfortable","read_more_text":"阅读全文","items":[{"kind":"article","type_label":"Article","date":"2026-11-18","title":"欢迎使用 Walnut：5 分钟上手指南","summary":"快速了解长文排版、Markdown 容器与 Wiki 双链。","url":"/hello-walnut","badge":"guide"},{"kind":"micro","type_label":"Micro","date":"2026-11-18","title":"","summary":"微内容没有标题和独立 URL，但在时间线中同样与长文同轨呈现。","url":"","badge":"指南"}]},"template_html":"<univers-timeline data-density=\"{{#if density}}{{density}}{{else}}comfortable{{/if}}\" class=\"univers-timeline block space-y-7\">\n  <div class=\"space-y-1.5 border-b univers-border-base pb-3.5 empty:hidden\">\n    {{#if heading}}<h2 class=\"text-2xl sm:text-3xl font-bold tracking-tight text-slate-900 dark:text-white\">{{heading}}</h2>{{/if}}\n    {{#if subheading}}<p class=\"text-sm text-slate-500 dark:text-slate-400\">{{subheading}}</p>{{/if}}\n  </div>\n  <div class=\"univers-timeline-track relative border-l-2 border-slate-200 dark:border-slate-800 pl-6 sm:pl-8 flex flex-col gap-7\">\n    {{#each items}}\n    <div class=\"relative space-y-2\">\n      <span class=\"univers-timeline-dot absolute -left-[31px] sm:-left-[39px] top-1.5 w-3 h-3 rounded-full univers-card-surface border-2\"></span>\n      <div class=\"flex flex-wrap items-center gap-2 text-xs font-mono text-slate-400 empty:hidden\">{{#if date}}<time>{{date}}</time>{{/if}}{{#if type_label}}<span class=\"px-2 py-0.5 rounded bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 font-bold\">{{type_label}}</span>{{/if}}{{#if badge}}<span class=\"px-2 py-0.5 rounded univers-badge-accent\">{{badge}}</span>{{/if}}</div>\n      {{#if title}}<h3 class=\"text-base sm:text-lg font-bold text-slate-900 dark:text-white leading-snug\">{{#if url}}<a href=\"{{url}}\" class=\"univers-link-accent\">{{title}}</a>{{else}}{{title}}{{/if}}</h3>{{/if}}\n      {{#if summary}}<p class=\"univers-timeline-summary text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">{{summary}}</p>{{/if}}\n      {{#if url}}<div><a href=\"{{url}}\" class=\"inline-flex items-center gap-1 text-xs font-bold univers-accent-text hover:underline\">{{#if read_more_text}}{{read_more_text}}{{else}}&rarr;{{/if}}</a></div>{{/if}}\n    </div>\n    {{/each}}\n  </div>\n</univers-timeline>"},{"slug":"univers-markdown","name":"独立 Markdown 正文 (Univers Markdown)","title":"独立 Markdown 正文 (Univers Markdown)","category":"content","icon":"edit_note","slots":["main"],"description":"单页独立 Markdown 正文块，套用主题正文排版","summary":"单页与专题页独立 Markdown 正文块，自动走主题 md_components 解析并复用正文排版。","ui_schema":[{"key":"title","label":"区块标题 (留空则隐藏)","type":"text","default":""},{"key":"content","label":"Markdown 正文内容","type":"markdown","widget":"markdown","default":"## 独立内容区块\n\n支持标准 Markdown 语法、`[[双链]]` 与主题 `md_components` 自定义容器。"}],"default_props":{"title":"","content":"## 独立内容区块\n\n支持标准 Markdown 语法、`[[双链]]` 与主题 `md_components` 自定义容器。"},"template_html":"<univers-markdown class=\"block\">\n  <div class=\"max-w-3xl mx-auto space-y-6\">\n    {{#if title}}<h2 class=\"text-2xl sm:text-3xl font-bold tracking-tight text-slate-900 dark:text-white border-b univers-border-base pb-3\">{{title}}</h2>{{/if}}\n    {{#if content}}<div class=\"walnut-article-content prose dark:prose-invert max-w-none text-slate-800 dark:text-slate-200 leading-relaxed space-y-6\">{{{content}}}</div>{{/if}}\n  </div>\n</univers-markdown>"}],"schemas":[{"slug":"projects","name":"开源项目与作品集 (Projects)","description":"展示开源仓库、工具或数字作品条目。","fields":[{"key":"title","label":"项目名称","type":"text","required":true},{"key":"summary","label":"一句话简介","type":"textarea","required":true},{"key":"category","label":"分类标签","type":"text","required":false},{"key":"tech_stack","label":"技术栈","type":"text","required":false},{"key":"site_url","label":"项目地址 / 链接","type":"url","required":false},{"key":"metrics","label":"状态 / 备注徽章","type":"text","required":false}]},{"slug":"links","name":"常用导航与书签 (Links)","description":"精选常用工具、技术文档与灵感站点书签。","fields":[{"key":"title","label":"站点名称","type":"text","required":true},{"key":"description","label":"推荐说明","type":"textarea","required":true},{"key":"url","label":"目标网址","type":"url","required":true},{"key":"category","label":"所属分类","type":"text","required":false}]}],"templates":[{"id":"tpl-univers-home","slug":"tpl-univers-home","name":"个人主页蓝图 (Minimal Home Template)","description":"极简首屏 + 精选项目展柜 + 最新随笔 + 碎碎念动态与页脚。","layout":"default","blocks":[{"id":"blk-home-nav","component":"univers-navbar","target_slot":"header","props":{}},{"id":"blk-home-hero","component":"univers-hero","target_slot":"main","props":{"layout":"auto","cover_image":""}},{"id":"blk-home-projects","component":"univers-dataset-viewer","target_slot":"main","props":{"layout":"grid","items":"@api:dataset:collection=projects&limit=3"}},{"id":"blk-home-articles","component":"univers-article-archive","target_slot":"main","props":{"variant":"clean","items":"@api:articles:limit=6"}},{"id":"blk-home-micros","component":"univers-content-feed","target_slot":"main","props":{"variant":"clean","items":"@api:micro:limit=6"}},{"id":"blk-home-cta","component":"univers-cta-banner","target_slot":"main","props":{"tone":"soft"}},{"id":"blk-home-footer","component":"univers-footer","target_slot":"footer","props":{"layout":"rich"}}]},{"id":"tpl-univers-article","slug":"tpl-univers-article","name":"文章阅读蓝图 (Article Detail Template)","description":"正文阅读器 + 右侧自动大纲目录与反向双链侧栏。","layout":"default","blocks":[{"id":"blk-art-nav","component":"univers-navbar","target_slot":"header","props":{}},{"id":"blk-art-view","component":"univers-article-view","target_slot":"main","props":{}},{"id":"blk-art-toc","component":"univers-toc-sidebar","target_slot":"sidebar","dataSource":"fetch_backlinks","props":{}},{"id":"blk-art-footer","component":"univers-footer","target_slot":"footer","props":{"layout":"simple"}}]},{"id":"tpl-univers-archive","slug":"tpl-univers-archive","name":"混排时间线归档模板 (Timeline Archive Template)","description":"在垂直时间线上按发布时间混排文章与短动态。","layout":"default","blocks":[{"id":"blk-arc-nav","component":"univers-navbar","target_slot":"header","props":{}},{"id":"blk-arc-timeline","component":"univers-timeline","target_slot":"main","props":{"density":"comfortable","items":"@api:feed:types=article,micro&limit=20"}},{"id":"blk-arc-footer","component":"univers-footer","target_slot":"footer","props":{"layout":"simple"}}]},{"id":"tpl-univers-projects","slug":"tpl-univers-projects","name":"项目展厅模板 (Projects Directory Template)","description":"网格展示项目集并搭配常见问题折叠卡片。","layout":"default","blocks":[{"id":"blk-prj-nav","component":"univers-navbar","target_slot":"header","props":{}},{"id":"blk-prj-viewer","component":"univers-dataset-viewer","target_slot":"main","props":{"layout":"grid","items":"@api:dataset:collection=projects&limit=12"}},{"id":"blk-prj-faq","component":"univers-faq-accordion","target_slot":"main","props":{"layout":"stack"}},{"id":"blk-prj-footer","component":"univers-footer","target_slot":"footer","props":{"layout":"simple"}}]},{"id":"tpl-univers-landing","slug":"tpl-univers-landing","name":"产品 / 作品发布页蓝图 (Product Landing Template)","description":"分栏首屏 + 特性矩阵 + 图文穿插 + 对比卡片 + 双栏问答 + 转化横幅 + 联系表单。","layout":"default","blocks":[{"id":"blk-lp-nav","component":"univers-navbar","target_slot":"header","props":{"variant":"default"}},{"id":"blk-lp-hero","component":"univers-hero","target_slot":"main","props":{"layout":"split","badge_text":"EDGE NATIVE","cover_image":"/theme/univers/assets/pipeline.svg"}},{"id":"blk-lp-grid","component":"univers-grid","target_slot":"main","props":{"columns":"3","variant":"card"}},{"id":"blk-lp-split","component":"univers-split-feature","target_slot":"main","props":{"variant":"boxed","image_url":"/theme/univers/assets/slots.svg"}},{"id":"blk-lp-cards","component":"univers-cards","target_slot":"main","props":{}},{"id":"blk-lp-faq","component":"univers-faq-accordion","target_slot":"main","props":{"layout":"split"}},{"id":"blk-lp-cta","component":"univers-cta-banner","target_slot":"main","props":{"tone":"contrast"}},{"id":"blk-lp-form","component":"univers-lead-form","target_slot":"main","props":{"layout":"split","tone":"soft"}},{"id":"blk-lp-footer","component":"univers-footer","target_slot":"footer","props":{"layout":"rich"}}]}],"layout_file":"templates/layout.html","layout_html":"<!DOCTYPE html>\n<html lang=\"{{page.locale}}\">\n<head>\n  {{edge_head}}\n</head>\n<body class=\"min-h-screen flex flex-col univers-shell-body antialiased transition-colors duration-200\">\n  <header data-slot=\"header\" class=\"sticky top-0 z-50 w-full backdrop-blur-md univers-header-bar empty:hidden\">{{slot:header:1}}</header>\n  <div data-slot=\"subnav\" class=\"w-full empty:hidden\">{{slot:subnav:2}}</div>\n  <div class=\"flex-1 w-full univers-page-backdrop\">\n    <div class=\"univers-shell max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-10 sm:py-12\">\n      <div class=\"univers-shell-grid\">\n        <main data-slot=\"main\" class=\"univers-main w-full min-w-0 space-y-14 sm:space-y-16\">{{slot:main}}</main>\n        <aside data-slot=\"sidebar\" class=\"univers-sidebar w-full min-w-0 space-y-6 empty:hidden\">{{slot:sidebar:3}}</aside>\n      </div>\n    </div>\n  </div>\n  <footer data-slot=\"footer\" class=\"mt-auto univers-footer-bar empty:hidden\">{{slot:footer:1}}</footer>\n  {{edge_foot}}\n</body>\n</html>\n","color_schemes":["light","dark"],"global_assets":{"styles":["/shared/app.css","assets/css/style.css"],"scripts":["assets/js/main.js"]}}', 'ver_univers_1'
);
