INSERT INTO pages (id, site_id, slug, parent_id, locale, translation_group_id, status, visibility, title, summary, cover_image_url, metadata, current_version_id, curator_id, published_at) VALUES (
  'page_projects', 'site_default', 'projects', '', 'zh-CN', 'tg_projects', 'published', 'public', '项目展厅', '精选开源小工具与创意网页作品清单。', '',
