  'art_hello_walnut_en', 'site_default', 'hello-walnut', 'en-US', 'tg_art_1', 'published', 'public', 'evergreen', 'Hello, Digital Garden: Why I Write Here', 'Notes on blending long-form essays, quiet status streams, and curated directories.', '',
  '{"folder":"essays","category":"Essays","tags":["writing","garden"],"reading_time":3,"template_id":"page_tpl_article"}', 'ver_art_hello_en_1', 'admin', CURRENT_TIMESTAMP, '2026-11-18 09:50:00'
);
INSERT INTO entity_versions (id, site_id, entity_type, entity_id, version_number, title, summary, content_raw, metadata_snapshot, commit_message, author_id) VALUES ('ver_art_hello_en_1', 'site_default', 'article', 'art_hello_walnut_en', 1, 'Hello, Digital Garden: Why I Write Here', 'Notes on blending long-form essays, quiet status streams, and curated directories.', 'Welcome to my digital garden. This opening essay shares the ideas behind organizing long-form writing, small software projects, and everyday notes in one calm place.

[[tip: Tip: Use the header controls anytime to toggle between Cosmic Mist light mode and Aurora Dark mode, or switch seamlessly between English and Chinese.]]

## 1. Mixing Essays, Field Notes, and Curated Directories

Different kinds of thinking deserve different formats:

- **Essays**: Structured reflections and technical deep dives paired with an automatic table of contents.
- **Field Notes**: Lightweight status updates, reading quotes, and half-formed sparks that belong in a stream rather than a formal post.
- **Projects & Bookmarks**: Clean structured showcases for tools worth keeping and websites worth revisiting.

### Linking Ideas Across Notes

Notes grow richer when connected together. Continue reading about my daily publishing setup in [[building-digital-garden|Building a Bilingual Digital Garden Workflow]].

## 2. Around the Site

1. Visit **Projects** for recent open tools and interactive starters.
2. Explore **Links** and **Gallery** for curated references and visual studies.
3. Browse **Archive** to follow everything chronologically.', '{}', 'Initial EN opening essay', 'admin');

